          if (get.attitude(player, event.player) > 0 && player.countCards('h') > 2 && (event.player.hp > 1 || player.countCards('hs', (card) => player.canSaveCard(card, event.player)) >= player.getDamagedHp() + event.player.getDamagedHp())) return 0;
          return 1;
