              var controls = _status.event.controls;
              if (controls.includes('选项一') && player.countCards('he', (card) => get.type(card) == 'equip' && 8 - get.value(card)) < 2) return '选项一';
              if (controls.includes('选项二') && player.countCards('h', (card) => 5 - get.value(card)) >= 2) return '选项三';
