      subSkill: {
        untarget: {
          mod: {
            targetEnabled(card, player, target) {
              var skill = 'dqzw_weiwo_untarget';
              var storage = target.storage[skill];
              var damaged = lib.skill[skill].getRoundDamaged;
              if (storage.includes(card.suit) && target != player && damaged(target)) return false;
            },
          },
          silent: true,
          charlotte: true,
          trigger: {
            source: 'damage',
          },
          filter(event, player) {
            return event.parent.skill == 'dqzw_weiwo';
          },
          getRoundDamaged(player) {
            var action = player.actionHistory;
            for (var index = action.length - 1; index >= 0; index--) {
              var history = action[index];
              for (var evt of history.sourceDamage) {
                if (evt.parent.skill == 'dqzw_weiwo') {
                  return true;
                }
              }
              if (history.isRound) break;
            }
            return false;
          },
          content() {
            player.markSkill(event.name);
          },
          intro: {
            content: '你不能成为其他角色使用$牌的目标',
          },
        },
      },
