    dqzw_huitian: {
      audio: 'ext:大权在握/audio/skill:2',
      enable: 'phaseUse',
      usable: 1,
      filter(event, player) {
        return (
          player.hasMark('dqzw_guchen') &&
          player.hasCard(function (card1) {
            return player.hasCard(function (card2) {
              if (player.getCards('hes').indexOf(card2) <= player.getCards('hes').indexOf(card1)) return false;
              return lib.inpile.some((name) => ['basic', 'trick'].includes(get.type(name)) && event.filterCard({ name: name }, player, event));
            }, 'hes');
          }, 'hes')
        );
      },
      chooseButton: {
        dialog(event, player) {
          var vcard = [];
          for (var name of lib.inpile) {
            var card = { name: name },
              type = get.type(card);
            if (['basic', 'trick'].includes(type)) {
              if (event.filterCard && event.filterCard(card, player, event)) {
                vcard.push([get.translation(type), '', name]);
                if (name == 'sha') {
                  for (var nature of lib.inpile_nature) {
                    card.nature = nature;
                    if (event.filterCard && event.filterCard(card, player, event)) {
                      vcard.push([get.translation(type), '', name, nature]);
                    }
                  }
                }
              }
            }
          }
          return ui.create.dialog(get.prompt('dqzw_huitian'), [vcard, 'vcard'], 'hidden');
        },
        check(button) {
          var player = _status.event.player;
          if (player.countCards('hs', button.link[2]) > 0) return 0;
          if (button.link[2] == 'wugu') return;
          var effect = player.getUseValue(button.link[2]);
          if (effect > 0) return effect;
          return 0;
        },
        backup(links, player) {
          return {
            log: false,
            popname: true,
            filterCard: true,
            selectCard: 2,
            complexCard: true,
            position: 'hes',
            check: (card) => 5 - get.value(card),
            viewAs: { name: links[0][2], nature: links[0][3] },
            precontent() {
              player.removeMark('dqzw_guchen');
            },
          };
        },
        prompt(links, player) {
          return '移去一枚<精>标记并将两张牌当做' + get.translation(links[0][3]) + '【' + get.translation(links[0][2]) + '】使用';
        },
      },
      ai: {
        order: 1,
        result: {
          player: 1,
        },
      },
      group: 'dqzw_huitian_effect',
      subSkill: {
        effect: {
          audio: 'dqzw_huitian',
          trigger: {
            player: 'useCard',
          },
          filter(event, player) {
            return player.hasMark('dqzw_guchen') && ['basic', 'trick'].includes(get.type(event.card));
          },
          prompt2(event, player) {
            return '移去一枚<精>标记令此牌' + (get.type(event.card) == 'basic' ? '伤害基数+1' : '不可被响应');
          },
          check(event, player) {
            if (get.type(event.card) == 'basic') {
              if (get.tag(event.card, 'damage')) {
                return !event.targets.every(
                  (target) =>
                    target.mayHaveShan() &&
                    !player.hasSkillTag(
                      'directHit_ai',
                      true,
                      {
                        target: target,
                        card: event.card,
                      },
                      true
                    )
                );
              }
              if (get.tag(event.card, 'recover')) return player.getDamagedHp() >= 2;
              return false;
            }
            if (get.type(event.card) == 'trick') return true;
            return false;
          },
          content() {
            player.removeMark('dqzw_guchen');
            if (get.type(trigger.card) == 'basic') {
              trigger.baseDamage++;
            } else {
              trigger.directHit.addArray(game.filterPlayer());
            }
          },
        },
      },
    },
