        player
          .chooseButton(['是否发动【宴戏】:选择加入【贰】阵营的角色', character], [1, character.length - 1])
          .set('ai', function (button) {
            if (ui.selected.buttons.length < _status.event._num) return 1;
            return 0;
          })
          .set('_num', get.rand(1, character.length - 1));
