    //当你受到伤害后,你可以令一名其他角色选择一项:交给你X张牌并将武将牌翻面,或弃置X张牌对伤害来源造成一点伤害(X为你已损失的体力值)
    dqzw_fangzhu: {
      audio: 'ext:大权在握/audio/skill:2',
      trigger: {
        player: 'damageEnd',
      },
      forced: true,
      async content(event, trigger, player) {
        //QQQ
        const { targets } = await player
          .chooseTarget(get.prompt2('refangzhu'), function (card, player, target) {
            return player != target;
          })
          .set('ai', function (target) {
            if (target.hasSkillTag('noturn')) return 0;
            if (get.attitude(player, target) == 0) return 0;
            if (get.attitude(player, target) > 0) {
              if (target.classList.contains('turnedover')) return 1000 - target.countCards('h');
              if (player.getDamagedHp() < 3) return -1;
              return 100 - target.countCards('h');
            } else {
              if (target.classList.contains('turnedover')) return -1;
              if (player.getDamagedHp() >= 3) return -1;
              return 1 + target.countCards('h');
            }
          })
          .forResult();
        if (targets && targets[0]) {
          var choice = ['交给' + get.translation(player) + get.cnNumber(player.getDamagedHp()) + '张牌并翻面'];
          if (trigger.source) {
            choice.push('弃置' + get.cnNumber(player.getDamagedHp()) + '张牌并对' + get.translation(trigger.source) + '造成一点伤害');
          }
          const { index } = await targets[0]
            .chooseControl()
            .set('choiceList', choice)
            .set('ai', function () {
              if (trigger.source && get.attitude(targets[0], trigger.source) < 0) {
                return 1;
              }
              return 0;
            })
            .forResult();
          const num = targets[0].countCards('he') >= player.getDamagedHp() ? player.getDamagedHp() : targets[0].countCards('he');
          if (index == 1) {
            trigger.source.damage(targets[0]);
            if (num > 0) {
              targets[0].chooseToDiscard(num, true);
            }
          } else {
            targets[0].turnOver();
            const { cards } = await targets[0].chooseCard(num).forResult();
            if (cards && cards[0]) {
              targets[0].give(cards, player, 'giveAuto');
            }
          }
        }
      },
      ai: {
        maixie: true,
        maixie_hp: true,
        effect: {
          target(card, player, target) {
            if (get.tag(card, 'damage')) {
              if (player.hasSkillTag('jueqing', false, target)) return [1, -1.5];
              if (target.hp <= 1) return;
              if (!target.hasFriend()) return;
              var hastarget = false;
              var turnfriend = false;
              var players = game.filterPlayer();
              for (var i of players) {
                if (get.attitude(target, i) < 0 && !i.isTurnedOver()) {
                  hastarget = true;
                }
                if (get.attitude(target, i) > 0 && i.isTurnedOver()) {
                  hastarget = true;
                  turnfriend = true;
                }
              }
              if (get.attitude(player, target) > 0 && !hastarget) return;
              if (turnfriend || target.hp == target.maxHp) return [0.5, 1];
              if (target.hp > 1) return [1, 0.5];
            }
          },
        },
      },
    },
