    dqzw_leici: {
      audio: 'ext:大权在握/audio/skill:2',
      forced: true,
      trigger: {
        player: 'dying',
      },
      filter(event, player) {
        var action = player.actionHistory;
        for (var index = action.length - 1; index >= 0; index--) {
          var history = action[index];
          if (history.useSkill && history.useSkill.some((evt) => evt.skill == 'dqzw_leici')) return false;
          if (history.isRound) break;
        }
        return game.hasPlayer((target) => target != player && target.countCards('he'));
      },
      content() {
        'step 0';
        player.chooseTarget([1, Infinity], get.prompt2(event.name), lib.filter.notMe).set('ai', function (target) {
          return get.attitude(player, target);
        });
        ('step 1');
        if (result.bool) {
          var targets = result.targets.sortBySeat();
          event.targets = targets;
        } else {
          event.finish();
        }
        ('step 2');
        player
          .chooseCardOL(targets, 'he')
          .set('ai', function (card) {
            var player = _status.event.player,
              source = _status.event.source;
            var bool = player.storage.dqzw_beitong_effect == source;
            if (get.attitude(player, source) < 0) {
              if (bool) return get.unuseful2(card);
              return 0;
            }
            if (bool) return source.getUseValue(card);
            return (get.color(card) == 'red' ? 20 : 8) - get.value(card);
          })
          .set('source', player);
        ('step 3');
        var gain_list = [],
          togain = [],
          map = { red: 0, black: 0 };
        for (var index = 0; index < result.length; index++) {
          if (result[index].bool) {
            var target = targets[index],
              cards = result[index].cards;
            var bool = target.storage.dqzw_beitong_effect == player;
            gain_list.push([target, cards]);
            togain.addArray(cards);
            map[bool ? 'red' : get.color(cards[0])]++;
          }
        }
        if (gain_list.length) {
          if (map.red > map.black) event.recover = true;
          if (gain_list.length == 1) {
            player.gain(togain, gain_list[0][0], 'giveAuto');
          } else {
            game.loseAsync({
              gain_list: gain_list,
              gainer: player,
              cards: togain,
              animate: 'giveAuto',
            }).setContent(lib.skill[event.name].gaincardMultiple);
          }
        } else {
          event.finish();
        }
        ('step 4');
        if (event.recover) {
          player.recover(1 - player.hp);
        }
      },
      gaincardMultiple() {
        'step 0';
        event.type = 'gain';
        if (event.animate == 'give' || event.animate == 'gain2') event.visible = true;
        for (var list of event.gain_list) {
          event._lose = true;
          list[0].lose(list[1], ui.special).set('type', 'gain').set('forceDie', true).set('getlx', false);
        }
        ('step 1');
        switch (event.animate) {
          case 'draw': {
            for (var list of event.gain_list) {
              if (get.itemtype(list[1]) == 'card') list[1] = [list[1]];
              if (event._lose) list[1] = list[1].filter((card) => !cards.includes(card) || !list[0].getCards('hejsx').includes(card));
              if (list[1].length) event.gainer.$draw(list[1].length);
            }
            break;
          }
          case 'gain': {
            for (var list of event.gain_list) {
              if (get.itemtype(list[1]) == 'card') list[1] = [list[1]];
              if (event._lose) list[1] = list[1].filter((card) => !cards.includes(card) || !list[0].getCards('hejsx').includes(card));
              if (list[1].length) event.gainer.$gain(list[1].length);
            }
            break;
          }
          case 'gain2':
          case 'draw2': {
            for (var list of event.gain_list) {
              if (get.itemtype(list[1]) == 'card') list[1] = [list[1]];
              if (event._lose) list[1] = list[1].filter((card) => !cards.includes(card) || !list[0].getCards('hejsx').includes(card));
              if (list[1].length) event.gainer.$gain2(list[1]);
            }
            break;
          }
          case 'give':
          case 'giveAuto': {
            if (!event.gainer) break;
            for (var list of event.gain_list) {
              if (get.itemtype(list[1]) == 'card') list[1] = [list[1]];
              if (event._lose) list[1] = list[1].filter((card) => !cards.includes(card) || !list[0].getCards('hejsx').includes(card));
              var shown = list[1].slice(0),
                hidden = [];
              if (event.animate == 'giveAuto') {
                for (var card of list[1]) {
                  if (event.getl(list[0]).hs.includes(card)) {
                    shown.remove(card);
                    hidden.push(card);
                  }
                }
              }
              if (shown.length) list[0].$give(shown, event.gainer);
              if (hidden.length) list[0].$giveAuto(hidden, event.gainer);
            }
            break;
          }
          default: {
            event.finish();
          }
        }
        var next = event.gainer.gain(cards);
        next.getlx = false;
        if (event.visible) next.visible = true;
        if (event.giver) next.giver = list[0];
        if (event.gaintag) next.gaintag.addArray(event.gaintag);
        ('step 2');
      },
    },
