      filter(evnet, player) {
        return player.getSkills().some((skill) => lib.skill[skill] && lib.skill[skill].zhaoyin) && !evnet.numFixed && game.hasPlayer((target) => target != player && target.countGainableCards(player, 'he'));
      },
      content() {
        'step 0';
        var group_map = {};
        game.players.forEach(function (target) {
          if (!group_map[target.group]) group_map[target.group] = game.countPlayer((value) => value.group == target.group);
        });
        var maxNum = Math.max(...Object.values(group_map));
        player
          .chooseTarget('选择【昭隐】的目标', function (card, player, target) {
            return target != player && target.countGainableCards(player, 'he');
          })
          .set('ai', function (target) {
            var att = get.attitude(_status.event.player, target);
            if (att > 0) return 0;
            if (group_map[target.group] == maxNum) att -= group_map[target.group];
            return -att;
          });
        event.maxNum = maxNum;
        ('step 1');
        if (result.bool) {
          trigger.num--;
          var target = result.targets[0];
          player.line(target);
          game.log(player, '对', target, '发动了', '#g【昭隐】');
          player.gainPlayerCard(target, true, 'he');
          if (game.countPlayer((value) => value.group == target.group) == event.maxNum) {
            event.trigger('zhaoyin');
          }
        }
      },
