    dqzw_hunhun: {
      audio: 'ext:大权在握/audio/skill:2',
      trigger: {
        player: ['chooseToUseBefore', 'chooseToRespondBefore'],
      },
      forced: true,
      content() {
        'step 0';
        player
          .chooseTarget(true, function (card, player, target) {
            if (target == player) return false;
            if (player.hasSkill('dqzw_ganghui')) {
              if (
                player.group != 'jin' &&
                game.hasPlayer(function (current) {
                  return current.group == player.group && _status.currentPhase == current;
                })
              )
                return target.group == player.group && _status.currentPhase == target;
            } else {
              if (
                game.hasPlayer(function (current) {
                  return current.group == player.group && _status.currentPhase == current;
                })
              )
                return target.group == player.group && _status.currentPhase == target;
            }
            return true;
          })
          .set('prompt', '昏阍')
          .set('prompt2', '请选择你的托管对象');
        ('step 1');
        if (result.bool) {
          if (
            player.countCards('h', function (card) {
              return trigger.filterCard(card, player, trigger);
            }) &&
            trigger.respondTo
          )
            trigger.forced = true;
          var target = result.targets[0];
          player._trueMe = target;
          game.addGlobalSkill('autoswap');
          if (player == game.me) {
            game.notMe = true;
          }
          var next = game.createEvent('dqzw_hunhun_clear');
          next.player = player;
          next.target = target;
          next.setContent(function () {
            if (player == game.me) {
              if (!game.notMe) game.swapPlayerAuto(player._trueMe);
              else delete game.notMe;
            }
            delete player._trueMe;
          });
          event.next.remove(next);
          trigger.after.push(next);
        }
      },
    },
    dqzw_longhui: {
      audio: 'ext:大权在握/audio/skill:2',
      enable: ['chooseToUse', 'chooseToRespond'],
      prompt: '将♦️️手牌当做火【杀】,♥️️手牌当做【桃】,♣️️手牌当做【闪】,♠️️手牌当做【无懈可击】使用或打出',
      viewAs(cards, player) {
        var name = false;
        var nature = null;
        switch (cards[0]?.suit) {
          case 'club':
            name = 'shan';
            break;
          case 'diamond':
            name = 'sha';
            nature = 'fire';
            break;
          case 'spade':
            name = 'wuxie';
            break;
          case 'heart':
            name = 'tao';
            break;
        }
        if (name) return { name: name, nature: nature };
        return null;
      },
      check(card) {
        var player = _status.event.player;
        if (_status.event.type == 'phase') {
          var max = 0;
          var name2;
          var list = ['sha', 'tao'];
          var map = { sha: 'diamond', tao: 'heart' };
          for (var i = 0; i < list.length; i++) {
            var name = list[i];
            if (
              player.countCards('hs', function (card) {
                return (name != 'sha' || get.value(card) < 5) && card.suit == map[name];
              }) > 0 &&
              player.getUseValue({ name: name, nature: name == 'sha' ? 'fire' : null }) > 0
            ) {
              var temp = get.order({ name: name, nature: name == 'sha' ? 'fire' : null });
              if (temp > max) {
                max = temp;
                name2 = map[name];
              }
            }
          }
          if (name2 == card.suit) return name2 == 'diamond' ? 5 - get.value(card) : 20 - get.value(card);
          return 0;
        }
        return 1;
      },
      position: 'hs',
      filterCard(card, player, event) {
        event = event || _status.event;
        var filter = event._backup.filterCard;
        var name = card.suit;
        if (name == 'club' && filter({ name: 'shan', cards: [card] }, player, event)) return true;
        if (name == 'diamond' && filter({ name: 'sha', cards: [card], nature: 'fire' }, player, event)) return true;
        if (name == 'spade' && filter({ name: 'wuxie', cards: [card] }, player, event)) return true;
        if (name == 'heart' && filter({ name: 'tao', cards: [card] }, player, event)) return true;
        return false;
      },
      filter(event, player) {
        var filter = event.filterCard;
        if (filter({ name: 'sha', nature: 'fire' }, player, event) && player.countCards('hs', { suit: 'diamond' })) return true;
        if (filter({ name: 'shan' }, player, event) && player.countCards('hs', { suit: 'club' })) return true;
        if (filter({ name: 'tao' }, player, event) && player.countCards('hs', { suit: 'heart' })) return true;
        if (filter({ name: 'wuxie' }, player, event) && player.countCards('hs', { suit: 'spade' })) return true;
        return false;
      },
      ai: {
        respondSha: true,
        respondShan: true,
        skillTagFilter(player, tag) {
          var name;
          switch (tag) {
            case 'respondSha':
              name = 'diamond';
              break;
            case 'respondShan':
              name = 'club';
              break;
            case 'save':
              name = 'heart';
              break;
          }
          if (!player.countCards('hs', { suit: name })) return false;
        },
        order(item, player) {
          if (player && _status.event.type == 'phase') {
            var max = 0;
            var list = ['sha', 'tao'];
            var map = { sha: 'diamond', tao: 'heart' };
            for (var i = 0; i < list.length; i++) {
              var name = list[i];
              if (
                player.countCards('hs', function (card) {
                  return (name != 'sha' || get.value(card) < 5) && card.suit == map[name];
                }) > 0 &&
                player.getUseValue({ name: name, nature: name == 'sha' ? 'fire' : null }) > 0
              ) {
                var temp = get.order({ name: name, nature: name == 'sha' ? 'fire' : null });
                if (temp > max) max = temp;
              }
            }
            max /= 1.1;
            return max;
          }
          return 2;
        },
      },
      hiddenCard(player, name) {
        if (name == 'wuxie' && _status.connectMode && player.countCards('hs') > 0) return true;
        if (name == 'wuxie') return player.countCards('hs', { suit: 'spade' }) > 0;
        if (name == 'tao') return player.countCards('hs', { suit: 'heart' }) > 0;
      },
    },
