          if (typeof lib.card[event.card.name].selectTarget == 'number' && event.targets.length > lib.card[event.card.name].selectTarget) return true;
          else if (typeof lib.card[event.card.name].selectTarget == 'object' && event.targets.length > lib.card[event.card.name].selectTarget[1]) return true;
