    dqzw_tameng: {
      audio: 'ext:大权在握/audio/skill:2',
      forced: true,
      trigger: {
        player: 'useCard',
      },
      filter(event, player, name) {
        return event.cards && event.cards.filterInD().length == 2;
      },
      content: async function (event, trigger, player) {
        const next = game.createEvent('preview', false);
        next._event = trigger;
        next.setContent(lib.skill[event.name].preview);
      },
      preview: async function (event, trigger, player) {
        await event.trigger('previewBefore');
        const info_map = {},
          _event = event._event;
        game.filterPlayer().forEach(function (target) {
          info_map[target.playerid] = target.hp;
        });
        game.log('预演开始 事件:', '#y' + _event.name);
        await event.trigger('previewBegin');
        const source = _event.player || _event.parent.player || _status.currentPhase;
        source.storage.dqzw_tameng = info_map;
        source.markSkill('dqzw_tameng');
        const next = game.createEvent('preview_recover', false, { next: [] });
        next._event = _event;
        next.info_map = info_map;
        next.source = source;
        next.setContent(async function (event, trigger, player) {
          const source = event.source,
            _event = event._event;
          source.unmarkSkill('dqzw_tameng');
          if (_event.name == 'phase') {
            _event.player.phase('nodelay');
          } else {
            if (lib.phaseName.includes(_event.name)) {
              const next = _event.player[_event.name]();
              event.next.remove(next);
              _event.after.unshift(next);
            } else {
              if (_event.name == 'useCard' && _event.addCount !== false) {
                _event.addCount = false;
                if ((_event.player.getStat('card')[_event.card.name] || 0) > 0) {
                  _event.player.getStat('card')[_event.card.name]--;
                }
              } else {
                if (lib.skill[_event.name] && _event.addCount !== false) {
                  _event.addCount = false;
                  if ((_event.player.getStat('skill')[_event.name] || 0) > 0) {
                    _event.player.getStat('skill')[_event.name]--;
                  }
                } else {
                  _event.addCount = false;
                }
              }
            }
          }
          new Promise((resolve) => {
            game.filterPlayer().forEach((target) => {
              game.log(target, '将体力从', get.cnNumber(target.hp, true), '改为', get.cnNumber(event.info_map[target.playerid], true));
              target.changeHp(event.info_map[target.playerid] - target.hp)._triggered = null;
            });
            setTimeout(() => {
              resolve();
            }, 1000);
          });
          await event.trigger('previewEnd');
          game.log('预演结束');
          await event.trigger('previewAfter');
        });
        _event.after.unshift(next);
      },
      marktext: '演',
      intro: {
        name: '预演',
        content(storage) {
          if (!storage || !Object.keys(storage).length) return '无信息';
          var str = '所有角色于预演开始时的体力值:<br>';
          game.filterPlayer2().forEach(function (target) {
            if (target.playerid in storage) {
              var info = get.translation(target) + ':' + storage[target.playerid];
              if (!target.isIn()) info = '<span style="opacity:0.5">' + info + '(已故)</span>';
              str += '<li>' + info;
            }
          });
          return str;
        },
      },
      group: 'dqzw_tameng_effect',
      subSkill: {
        effect: {
          audio: 'dqzw_tameng',
          trigger: {
            player: 'useCard1',
          },
          filter(event, player, name) {
            return event.cards && event.cards.some((card) => card.name == event.card.name);
          },
          prompt2: '你可以将其中一张同名牌置入弃牌堆,若如此做,重置〖摧险〗并令此牌伤害值+2',
          content: async function (event, trigger, player) {
            const cards = trigger.cards.filter((card) => card.name == trigger.card.name);
            const { links } =
              cards.length == 1
                ? cards
                : await player
                  .chooseButton(['踏梦', '<div class="text center">将其中一张牌置入弃牌堆</div>', trigger.cards], true)
                  .set('filterButton', function (button) {
                    const trigger = _status.event.getTrigger();
                    return button.link.name == trigger.card.name;
                  })
                  .forResult();
            game.log(player, '将', links, '置入了弃牌堆');
            await game.cardsDiscard(links);
            lib.skill.dqzw_cuixian_backup.init(player, 'dqzw_cuixian_backup');
            if (get.tag(trigger.card, 'damage') > 0) trigger.baseDamage += 2;
          },
        },
      },
    },
